      "path": "inputs/migration_255807/regulation.json",
      "sha256": "6b5662f2b5e5e6c070e99c3e3133726f8dff5ea34150775645f4eb5613921d84"
    },
    {
      "path": "inputs/migration_255807/fixtures.json",
      "sha256": "365ede9c36914c111fe912a7461d5d86869e4928e87f2ef1218cf5dc8704322b"
    },
    {
      "path": "inputs/migration_255807/proposal.json",
      "sha256": "67e5df17f9d6b0bd6bbbd057b666edf8457fee715ed3522d9a0684fdad0a2a4f"
